      final dir = Directory('prompts/skills');
      final sources = <String, String>{
        for (final d in dir.listSync().whereType<Directory>())
          d.uri.pathSegments.reversed.toList()[1]: File(
            '${d.path}/SKILL.md',
          ).readAsStringSync(),
