/// Byte-level content verdict for one SKILL.md — the single-read
/// (readAsBytes) core of [builtinSkillSourceViolations] so the byte
/// count and the inspected text can never disagree between two reads.
List<String> builtinSkillMdByteViolations(
  String name,
  List<int> content, {
  int minBytes = builtinSkillMinBytes,
}) {
  final text = utf8.decode(content);
  if (text.trim().isEmpty) {
    return ['built-in skill "$name": SKILL.md ships EMPTY '
        '(0 bytes of content — the gh-1275 incident shape)'];
  }
  if (content.length < minBytes) {
    return ['built-in skill "$name": SKILL.md is ${content.length} bytes, below '
        'the $minBytes-byte floor — a frontmatter-only stub is not a usable skill'];
  }
  return const [];
