              'scripts/gen_prompts.dart`',
        );
      }
    });
  });

  group('verifyBuiltinSkills — the composed gate the workflows run', () {
    test('current tree passes end to end', () async {
      expect(await guard.verifyBuiltinSkills(repoRoot: '.'), isEmpty);
    });
  });
